"""Execution: CPP historical clauses integrated with CP and LEP."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=(LEP,)):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(668,'Competência executória segue juiz indicado na organização judiciária e, na ausência, juiz da sentença, conforme LEP65.', ['Distinguir julgamento e execução.', 'Referências ao presidente do júri/tribunal precisam ser integradas à competência atual.'], 'Não presumir que toda decisão do júri permanece em execução com seu presidente apesar de vara competente.', 'Vara de execução definida pela lei local recebe título condenatório.', 'Sem juiz especializado indicado, examina-se competência supletiva da sentença.', ['Organização judiciária define juiz da execução? Sim.', 'Presidente do júri é sempre executor exclusivo? Não.'], 'Juízo executório','Órgão competente para efetivar a sanção.')
add(669,'Trânsito em julgado e efeitos da sentença exigem leitura das garantias atuais; exceções antigas não criam prisão automática.', ['Separar cautelar e execução.', 'Absolvição permite soltura se não houver outro título válido.', 'Júri possui regime específico do Tema1068.'], 'Não aplicar barreira antiga de pena máxima de oito anos para negar soltura após absolvição.', 'Réu absolvido sem outro título de prisão é liberado.', 'Preventiva de outro processo precisa ser examinada por fundamento próprio.', ['Pena máxima de oito anos impede toda soltura do absolvido? Não.', 'Outro título válido exige análise própria? Sim.'], 'Efeitos atuais da sentença','Consequências delimitadas pelo regime constitucional.',[LEP,CF])
add(670,'Absolvição confirmada ou proferida na apelação exige efetivar alvará e comunicar primeiro grau.', ['Cumprimento célere da decisão.', 'Verificar outro motivo legal de custódia.'], 'Decisão absolutória não pode ficar sem implementação por mera espera administrativa.', 'Tribunal absolve e determina expedição do alvará pertinente.', 'Outro mandado válido impede presumir liberdade física sem conferência.', ['Relator promove alvará na hipótese? Sim.', 'Comunicação ao primeiro grau é dispensável? Não.'], 'Alvará de soltura','Ordem judicial para cessar custódia atingida pela decisão.')
add(671,'Incidentes da execução são decididos pelo juiz competente, integrado às atribuições da LEP66.', ['Questões de cumprimento são jurisdicionais.', 'Garantir participação e defesa cabíveis.'], 'Diretor não substitui juiz para decidir definitivamente incidente reservado à jurisdição.', 'Defesa suscita erro no cálculo e juízo executório decide.', 'Questão recursal da condenação pode ter via diferente do incidente executório.', ['Incidente é resolvido pelo juiz competente? Sim.', 'Diretor decide sozinho toda questão executória? Não.'], 'Incidente executório','Questão surgida no cumprimento da sanção.')
add(672,'Tempo de prisão e internação pertinente pode ser abatido da pena por detração, conforme CP42.', ['Considerar custódia no Brasil ou exterior nos pressupostos legais.', 'Distinguir detração e remição.', 'Evitar contagem dupla do mesmo período.'], 'Detração não é crédito irrestrito para crimes futuros nem autoriza descontar qualquer internação sem vínculo pertinente.', 'Noventa dias de prisão provisória do caso entram no cálculo cabível.', 'Dias já computados não devem ser abatidos duas vezes.', ['Detração difere de remição por trabalho ou estudo? Sim.', 'Mesmo período pode ser contado duas vezes? Não.'], 'Detração','Abatimento do período legalmente computável.',[CP,LEP])
add(673,'Custódia que alcança duração da pena requer controle imediato; ressalva antiga de oito anos não autoriza excesso automático.', ['Comparar título, duração e situação recursal.', 'Apelação pode continuar após soltura.'], 'Recurso acusatório não permite por si manter prisão além do limite sem fundamento atual válido.', 'Condenado já permaneceu preso por tempo igual à pena e não tem outro título válido; examina-se soltura.', 'Outra preventiva fundamentada é analisada separadamente, não por rótulo da pena máxima.', ['Soltura impede julgamento da apelação? Não.', 'Recurso acusatório legitima automaticamente excesso? Não.'], 'Controle de duração','Prevenção da prisão além dos limites válidos.',[LEP,CF])
add(674,'Guia formaliza execução da pena privativa de liberdade, integrada aos artigos105–107 da LEP.', ['Título e dados necessários devem ser conferidos.', 'Soma ou unificação exige competência própria.'], 'Guia não cria condenação nem permite ignorar regime, detração e eventual unificação.', 'Condenação definitiva com custódia exige guia para execução regular.', 'Nova condenação requer atualizar cálculo sob órgão competente.', ['Guia formaliza título de execução? Sim.', 'Pode criar pena que a sentença não impôs? Não.'], 'Guia de recolhimento','Documento judicial de ingresso regular na execução.')
add(675,'Providências de prisão e encaminhamento executório precisam respeitar título, regime e pressupostos atuais.', ['Trânsito em julgado deve ser examinado.', 'Reforma de absolvição não gera prisão automática em toda hipótese.', 'Prisão especial tem regras próprias e limites temporais.'], 'Não copiar§1 como execução genérica imediata após qualquer apelação condenatória; integrar CPP283 e regime específico do júri.', 'Condenação definitiva impõe cumprimento conforme regime e ordem judicial válida.', 'Tribunal reforma absolvição fora do júri; ausência de fundamento cautelar não é suprida pelo texto histórico.', ['Toda reforma de absolvição permite prisão automática? Não.', 'Regime fixado deve ser respeitado? Sim.'], 'Título executório','Fundamento judicial válido para cumprimento da sanção.',[LEP,CF])
add(676,'Guia identifica condenado, título e duração; LEP106 exige conjunto atual de informações e retificação.', ['Incluir denúncia, sentença e certidão pertinente.', 'Não ignorar alterações de início ou tempo.', 'Múltiplas penas exigem soma/unificação no sistema atual.'], 'Não ensinar fila mecânica de guias como substituta da unificação e cálculo atual.', 'Remição reconhecida exige atualizar término calculado.', 'Duas condenações são apreciadas no regime da LEP111, não só aguardando fim da primeira guia.', ['Guia deve refletir alteração de duração? Sim.', 'Unificação pode ser ignorada por haver duas guias? Não.'], 'Retificação da guia','Atualização documental da situação executória.')
add(677,'Texto prevê cópia da guia e aditamentos ao Conselho Penitenciário; integrar comunicação aos órgãos atuais da execução.', ['Ciência do MP na LEP106§1.', 'Não trocar comunicação por decisão sobre benefício.'], 'Receber cópia não torna Conselho juiz da execução nem titular de toda concessão.', 'Alteração da guia é comunicada conforme fluxo legal e institucional pertinente.', 'Parecer de órgão consultivo não dispensa decisão judicial quando exigida.', ['Cópia transforma Conselho em juiz? Não.', 'MP possui ciência prevista na LEP? Sim.'], 'Comunicação executória','Compartilhamento institucional dos dados pertinentes.')
add(678,'Recebimento da guia deve ser documentado; LEP107 também prevê ciência dos termos ao condenado.', ['Recibo integra autos.', 'Informação permite controle do cumprimento.'], 'Registro administrativo não dispensa guia judicial ou informação ao condenado prevista no regime atual.', 'Estabelecimento confirma recebimento e informa os termos da execução.', 'Divergência documental é comunicada, sem inventar pena diversa.', ['Recebimento exige documentação? Sim.', 'Direção pode substituir sentença por cálculo arbitrário? Não.'], 'Recibo de guia','Prova da entrega do documento executório.')
add(679,'Registro cronológico e anotações acompanham evolução da execução, integrado à LEP107§2.', ['Atualizar remições e retificações.', 'Manter rastreabilidade do título.'], 'Registro inicial não é cálculo imutável de duração.', 'Remição deferida é incorporada ao prontuário e cálculo.', 'Erro encontrado deve ser corrigido por procedimento adequado, não perpetuado por ordem cronológica.', ['Anotações acompanham alterações? Sim.', 'Registro inicial impede retificar cálculo? Não.'], 'Prontuário executório','Histórico atualizado do cumprimento da pena.')
add(680,'Tempo de custódia após condenação definitiva conta na pena mesmo em estabelecimento diverso do destinado.', ['Local inadequado não apaga período cumprido.', 'Distinguir contagem e legalidade das condições.'], 'Computar tempo não legitima permanência em regime mais gravoso por falta de vaga.', 'Condenado aguarda transferência preso; período pertinente integra cumprimento.', 'Direito ao regime adequado continua sujeito a controle, apesar de contagem do tempo.', ['Espera de transferência apaga dias cumpridos? Não.', 'Contagem legitima automaticamente regime indevido? Não.'], 'Tempo efetivamente cumprido','Período de custódia que não se perde pela localização.')
add(681,'Ordem de execução das penas exige integração ao CP76 e à soma ou unificação pela LEP111.', ['Texto ordena reclusão, detenção e prisão simples.', 'Prioridade da pena mais grave não dispensa regime atual.'], 'Não aplicar fila de espécies para ignorar cálculo conjunto ou direitos executórios.', 'Reclusão e detenção concorrentes são examinadas sob prioridade e unificação cabíveis.', 'Regime não é decidido apenas pelo nome da espécie sem cálculo legal.', ['Prioridade dispensa unificação pertinente? Não.', 'Pena mais grave orienta ordem de cumprimento? Sim.'], 'Ordem de cumprimento','Prioridade integrada ao cálculo atual.',[CP,LEP])
add(682,'Transtorno mental superveniente exige avaliação e providência judicial adequada, integrada à LEP e ao cuidado em saúde.', ['Distinguir tratamento e substituição por medida de segurança.', 'Urgência administrativa é comunicada imediatamente ao juízo.', 'Não prolongar custódia penal indefinidamente.'], 'Diagnóstico não autoriza prisão perpétua ou internação punitiva automática após término da pena; integrar LEP183 e garantias do tratamento.', 'Quadro grave é avaliado por profissionais e levado ao juiz para medida legal cabível.', 'Ao fim do título penal, necessidade de cuidado não cria novo título de prisão por vontade da direção.', ['Doença autoriza custódia penal indefinida? Não.', 'Substituição exige análise judicial própria? Sim.'], 'Saúde mental superveniente','Condição que demanda cuidado e decisão legal individualizada.')
add(683,'Direção comunica imediatamente óbito, fuga ou soltura ao juiz; óbito acompanha certidão.', ['Atualizar autos e situação executória.', 'Distinguir comunicação e decisão jurídica posterior.'], 'Fuga comunicada não autoriza sanção definitiva sem procedimento cabível.', 'Óbito é informado com certidão para providências judiciais.', 'Notícia de fuga desencadeia controles e apuração, sem presumir todo efeito sancionatório.', ['Óbito deve vir acompanhado de certidão? Sim.', 'Comunicação dispensa apuração de sanção? Não.'], 'Comunicação de ocorrência','Atualização imediata sobre custódia e execução.')
add(684,'Recaptura de evadido dispensa prévia nova ordem e pode ser realizada por qualquer pessoa nos limites legais.', ['Verificar identidade e situação de evasão.', 'Não dispensar proteção da integridade e entrega à autoridade.'], 'Regra não autoriza violência arbitrária nem capturar pessoa livre por mera suspeita.', 'Pessoa reconhecida como evadida é contida legalmente e entregue à autoridade.', 'Erro de identidade exige verificação, não prisão baseada só em aparência.', ['Recaptura exige sempre novo mandado prévio? Não.', 'Autoriza violência arbitrária? Não.'], 'Recaptura','Retomada legal da custódia do evadido.')
add(685,'Cumprida ou extinta a pena, deve ser efetivada liberdade, salvo outro motivo legal válido.', ['Alvará judicial e conferência dos títulos.', 'Medida de segurança exige fundamento atual próprio.'], 'Parágrafo histórico não restaura aplicação cumulativa automática de pena e medida de segurança do sistema antigo.', 'Pena cumprida sem outro título leva à expedição e cumprimento do alvará.', 'Necessidade de saúde não permite inventar medida detentiva após o fim da pena.', ['Pena cumprida garante liberdade se não houver outro título? Sim.', 'Parágrafo cria medida de segurança automática? Não.'], 'Extinção do cumprimento','Cessação da execução nos limites do título.',[LEP,CP])
add(686,'Pagamento da multa integra CP50 e execução atual perante juízo executório pelo CP51 e LEP164.', ['Distinguir pagamento e citação executiva.', 'Referências recursais antigas não criam cobrança antes do título exigido.'], 'Não transformar falta de pagamento em prisão; execução da multa tem regime próprio.', 'Após título definitivo, cobrança segue procedimento legal de multa.', 'Inadimplemento não autoriza converter valor em dias de cadeia.', ['Multa tem regime próprio de execução? Sim.', 'Não pagar permite prisão por conversão? Não.'], 'Execução da multa','Cobrança da sanção pecuniária no regime atual.',[CP,LEP])
add(687,'Parcelamento da multa exige pedido, situação econômica e decisão, conforme CP50 e LEP169.', ['Distinguir autorização e direito automático.', 'Regras antigas de prorrogação/caução devem ser integradas.', 'Fraude e inadimplemento têm consequências legais próprias.'], 'Não apresentar três meses e caução antiga como regime atual único; não recuperar conversão em prisão.', 'Condenado demonstra renda e pede prestações compatíveis; juiz examina.', 'Melhora econômica ou impontualidade pode afetar benefício segundo LEP, sem prisão por multa.', ['Pedido garante automaticamente qualquer parcelamento? Não.', 'Parcelamento exige decisão e exame econômico? Sim.'], 'Parcelamento da multa','Pagamento fracionado legalmente autorizado.',[CP,LEP])
add(688,'Cobrança judicial e descontos devem seguir CP50–51 e LEP164–170, com proteção do sustento.', ['Penhora e desconto possuem pressupostos próprios.', 'Não adotar sempre um quarto como desconto obrigatório.', 'Selo penitenciário e remissões antigas não definem meio atual universal.'], 'Insolvência não autoriza desconto que retire recursos indispensáveis nem converta multa em prisão.', 'Juízo examina renda antes de ordenar desconto legal.', 'Salário necessário à subsistência familiar exige proteção, não retirada automática de25%.', ['Desconto pode retirar sustento indispensável? Não.', 'Um quarto é desconto automático universal? Não.'], 'Cobrança proporcional','Execução pecuniária submetida aos limites legais.',[CP,LEP])
add(689,'Conversão histórica de multa em detenção ou prisão simples não integra regime atual do CP51.', ['Lei9.268/1996 afastou conversão.', 'Moeda de mil-réis é histórica.', 'Cobrança segue via executória própria.'], 'Não ensinar taxa antiga, mandado de prisão ou conversão de parcelas como solução atual para multa inadimplida.', 'Multa não paga é objeto de cobrança legal, não de cálculo de dias de prisão.', 'Mesmo devedor solvente que frustra pagamento não reativa a conversão antiga.', ['Multa pode virar prisão pelo art.689 antigo? Não.', 'Solvência reativa conversão revogada? Não.'], 'Conversão histórica','Mecanismo antigo afastado pelo regime posterior.',[CP,LEP])
add(690,'Cessação da antiga conversão por pagamento ou caução é parte de modelo histórico que não deve ser aplicado como atual.', ['Hoje não há conversão de multa em prisão.', 'Pagamento tem efeitos executórios próprios.'], 'Não propor prender primeiro e soltar depois de pagar multa com fundamento nesta regra antiga.', 'Quitação é registrada na cobrança da multa e seus efeitos cabíveis.', 'Prisão por outro título válido não desaparece só porque multa foi paga.', ['É correto prender por multa e liberar mediante caução antiga? Não.', 'Outro título prisional deve ser examinado separadamente? Sim.'], 'Regime histórico da multa','Regra sem aplicação automática após reformas.',[CP,LEP])
add(691,'Efeito condenatório relativo a função ou atividade exige título legal atual e comunicação ao órgão competente.', ['Integrar CP92 e legislação pertinente.', 'Não confundir pena restritiva e efeito da condenação.', 'Conferir se efeito é automático ou exige declaração na hipótese.'], 'Não presumir perda universal de função em toda condenação; reformas podem prever hipóteses específicas.', 'Sentença declara perda funcional legalmente cabível e comunica administração.', 'Condenação sem pressupostos do efeito não permite inventar perda de cargo.', ['Toda condenação implica perda automática de cargo? Não.', 'Comunicação depende do efeito cabível no título? Sim.'], 'Efeito funcional','Consequência da condenação sujeita à base legal.',[CP])
add(692,'Proteção da pessoa e dos bens diante de incapacidade ligada a poder familiar, tutela ou curatela exige regime atual e juízo competente.', ['Integrar CP92 e normas civis protetivas.', 'Pátrio poder é terminologia histórica.', 'Não presumir incapacidade em qualquer condenação.'], 'Condição do condenado não autoriza abandono de pessoa protegida nem efeito sem fundamento legal.', 'Efeito legalmente reconhecido é comunicado para providências de proteção.', 'Condenação diversa sem pressupostos não retira automaticamente poder familiar.', ['Providências visam proteger pessoa e bens? Sim.', 'Qualquer condenação retira poder familiar? Não.'], 'Proteção familiar','Salvaguarda civil diante do efeito penal cabível.',[CP,CF])
add(693,'Registro de efeitos familiares precisa observar regime atual; autoridade marital é concepção histórica incompatível com igualdade.', ['Integrar poder familiar e efeito legal cabível.', 'Não reproduzir superioridade do marido sobre cônjuge.'], 'Averbação não pode criar incapacidade por autoridade marital antiga ou automática em toda condenação.', 'Efeito válido relacionado ao poder familiar recebe registro cabível.', 'Não se registra perda de domínio marital sobre a esposa, conceito incompatível com Constituição.', ['Autoridade marital antiga deve ser ensinada como poder atual? Não.', 'Registro depende de efeito juridicamente válido? Sim.'], 'Igualdade familiar','Paridade constitucional e proteção no regime atual.',[CF,CP])
add(694,'Comunicações de interdição devem ser integradas às penas restritivas e efeitos atuais, não ao sistema antigo de penas acessórias.', ['Distinguir CP47 e CP92.', 'Rol de culpados não é consequência atual automática.', 'Registro respeita normas e finalidade pertinentes.'], 'Não recuperar pena acessória antiga nem indiscriminada divulgação pública de antecedentes.', 'Interdição temporária cabível é comunicada para cumprimento do direito restringido.', 'Efeito da condenação não vira pena acessória por mudar o nome do registro.', ['Sistema antigo de penas acessórias permanece íntegro? Não.', 'Interdição e efeito condenatório são sempre iguais? Não.'], 'Registro de interdição','Comunicação da restrição legalmente imposta.',[CP,LEP])
add(695,'Duração de interdição exige título e legislação atuais; remissão ao antigo CP72 não define automaticamente prazo vigente.', ['Distinguir pena restritiva e efeito permanente.', 'Aplicar CP47 e55 e LEP pertinentes.'], 'Não fixar termo final por referência a artigo antigo sem identificar sanção atual.', 'Interdição temporária é executada pelo período legal fixado no título.', 'Perda funcional como efeito distinto não recebe duração de pena restritiva por analogia automática.', ['CP72 antigo basta para definir prazo atual? Não.', 'Espécie da consequência precisa ser identificada? Sim.'], 'Duração da interdição','Limite temporal conforme título e sanção atual.',[CP,LEP])
add(696,'Sursis da pena exige requisitos atuais do CP77–82; prazo antigo geral de dois a seis anos não é regra comum atual.', ['Regra comum: suspensão de dois a quatro anos, pena até dois anos, requisitos legais.', 'Hipótese etária ou de saúde tem limites próprios.', 'Distinguir suspensão da pena e suspensão do processo.'], 'Não substituir CP77 pelos requisitos antigos nem negar benefício só por condenação anterior a multa.', 'Pena de um ano exige avaliar reincidência dolosa, circunstâncias e substituição antes do sursis.', 'Pessoa maior de setenta anos pode exigir análise da hipótese específica, sem aplicação a todos.', ['Prazo comum atual é dois a quatro anos? Sim.', 'Sursis da pena é suspensão do processo? Não.'], 'Sursis penal','Suspensão condicionada da execução da pena.',[CP,LEP])
add(697,'Decisão deve motivar concessão ou denegação da suspensão da pena nas hipóteses legais atuais.', ['Examinar CP77 e espécie de sursis.', 'Não automatizar por quantidade de pena.', 'Hipóteses especiais não se limitam à pena comum de dois anos.'], 'Não dizer que pena curta garante benefício nem omitir motivação ao negar.', 'Sentença identifica substituição cabível e explica por que sursis não se aplica.', 'Hipótese etária ou de saúde exige exame próprio dos limites legais.', ['Concessão ou negativa exige motivação? Sim.', 'Pena até dois anos garante sempre sursis? Não.'], 'Decisão sobre sursis','Exame fundamentado dos requisitos atuais.',[CP,LEP])
add(698,'Condições, audiência e fiscalização do sursis devem ser integradas ao CP78–79 e LEP156–163.', ['Condições adequadas ao fato e situação pessoal.', 'Comunicar mudança autorizada e descumprimento.', 'Fiscalização não autoriza condições arbitrárias.'], 'Remissão ao767 e modelo antigo não criam qualquer obrigação automática; distinguir hipótese comum e especial.', 'Beneficiário recebe ciência das condições na audiência pertinente e cumpre acompanhamento.', 'Mudança de residência exige comunicação adequada, não perda automática por deslocamento permitido.', ['Condições podem ser arbitrárias? Não.', 'Ciência e fiscalização são relevantes ao benefício? Sim.'], 'Condições do sursis','Obrigações legais individualizadas para suspensão.',[CP,LEP])
add(699,'No júri, presidente examina sursis na sentença quando cabível, integrado ao regime atual.', ['Requisitos materiais continuam necessários.', 'Competência executória posterior segue organização judicial e LEP.'], 'Presidência do júri não transforma todo condenado em beneficiário nem exclui juiz da execução.', 'Pena e circunstâncias permitem análise motivada do benefício na sentença do júri.', 'Pena incompatível com hipótese legal não recebe sursis por ter sido julgada por jurados.', ['Júri dispensa requisitos do sursis? Não.', 'Presidente aprecia matéria na sentença pertinente? Sim.'], 'Sursis no júri','Exame do benefício na decisão judicial do procedimento.',[CP,LEP])
add(700,'Suspensão da pena não elimina automaticamente multa ou outras consequências; integrar CP80 e sistema atual.', ['CP80 exclui multa e penas restritivas de direitos da suspensão.', 'Penas acessórias são referência histórica.', 'Efeitos e custas têm regime próprio.'], 'Não ensinar sursis como cancelamento integral da condenação nem restaurar sistema acessório antigo.', 'Execução corporal é suspensa com condições, mas multa não desaparece por isso.', 'Obrigação pecuniária ou efeito funcional exige fundamento próprio e exame pertinente.', ['Sursis apaga automaticamente multa? Não.', 'Pena acessória antiga pode ser restaurada pelo texto? Não.'], 'Limites do sursis','Consequências que não são apagadas pela suspensão.',[CP,LEP])
assert len(rows)==33
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'execution units reviewed')
